from h import *
L=[]
L.append(R(3018,"Kotak Makan Siang Gulungan Daging Sapi Tortilla","Kotak Makan Siang Gulungan Daging Sapi Tortilla dari ahli gizi DaVita, Sara, adalah cara cepat membuat makanan untuk di rumah maupun dibawa bepergian. Resep ramah ginjal ini adalah perpaduan irisan daging sapi panggang, bawang merah bombai, paprika, mentimun, selada, dan krim keju, semuanya dibungkus dalam tortilla tepung terigu. Anggur dan almond meningkatkan serat dan menjadikannya hidangan lengkap.","1","1 kotak makan siang",
["2-1/2 ons daging sapi panggang matang","1 iris bawang merah bombai","1/4 paprika merah","4 iris mentimun","1 lembar daun selada romaine","1 tortilla tepung terigu, 6 inci","1 sendok makan krim keju kocok","1/2 sendok teh campuran bumbu herbal Mrs. Dash","1/2 cangkir anggur","10 butir almond, tanpa garam"],
["Iris daging sapi panggang dan mentimun; cincang bawang bombai dan paprika. Buang tulang daun dari daun selada romaine.","Untuk membuat gulungan daging sapi, oleskan krim keju pada tortilla. Susun irisan daging sapi panggang dan sayuran di atasnya. Taburi dengan bumbu herbal.","Gulung tortilla seperti kue gulung dan potong menjadi 4 bagian.","Letakkan gulungan, anggur, dan almond di piring atau di wadah makan siang bersekat."],
["Saran minuman: limun, air soda berperisa, soda lemon-limau, teh atau kopi seduh segar.","Untuk makanan yang dibawa bepergian, kemas kotak makan siang dengan kantong es agar makanan tetap dingin hingga siap disantap."],["3 daging","1 karbohidrat","1 sayuran, rendah kalium","1 buah, rendah kalium"]))
L.append(R(3019,"Bola Daging dan Nasi","Bola Daging dan Nasi bukanlah nama asli resep lezat dan ramah ginjal ini. Bola daging sapi dan nasi ini dijuluki Porcupine Balls (Bola Landak) karena nasinya mencuat seperti duri, persis seperti landak. Resep ini berasal dari ahli gizi ginjal DaVita, Ken dari Missouri, dan merupakan favorit keluarga lama yang telah dicoba dan diuji selama bertahun-tahun.","4","3 ons atau 6 bola daging",
["1 pon daging sapi giling tanpa lemak","1 butir telur besar","1 cangkir nasi putih instan","3/4 sendok teh campuran bumbu herbal Mrs. Dash®","2-1/4 cangkir air"],
["Dalam mangkuk besar, campurkan daging sapi giling, telur, dan nasi.","Setelah tercampur rata, bentuk menjadi 24 bola kecil.","Cokelatkan bola-bola di wajan pada semua sisinya.","Campurkan bumbu herbal Mrs. Dash® dengan air.","Tuang dengan hati-hati campuran air dan Mrs. Dash ke dalam wajan berisi bola daging.","Didihkan air.","Tutup dan didihkan perlahan selama 20 hingga 30 menit, sambil membalik bola-bola ke semua sisi."],
["Untuk hidangan yang lebih rendah lemak, ganti daging sapi giling dengan daging kalkun giling.","Jika Anda menjalani diet protein lebih rendah, sesuaikan porsi dengan rencana makan Anda."],["3 daging","1 karbohidrat","1 lemak"]))
L.append(R(3020,"Grits Keju","Rasa ekstra pada keju yang tajam membuat hidangan ini terasa keju sekaligus tetap ramah ginjal. Cobalah Grits Keju dengan telur untuk sarapan atau dengan udang untuk makan malam.","2","3/4 cangkir (2/3 cangkir jika lebih kental)",
["1 cangkir air","1/2 cangkir susu rendah lemak 2%","1/8 sendok teh garam (opsional)","1/3 cangkir grits putih atau kuning","2 sendok teh mentega tanpa garam","4 sendok makan keju cheddar tajam parut"],
["Dalam panci sedang, panaskan air, susu, dan garam dengan api sedang-besar hingga mendidih.","Masukkan grits dan aduk. Kecilkan api dan tutup panci sebagian dengan tutupnya. Agar grits halus, aduk sesering mungkin.","Masak selama 15 hingga 20 menit untuk grits tradisional, atau 8 hingga 9 menit untuk grits yang cepat matang.","Angkat panci dari api dan aduk mentega.","Bagi menjadi 2 porsi dan taburi setiap porsi dengan 2 sendok makan keju parut. Aduk keju dan sajikan selagi hangat."],
["Keju cheddar tajam atau ekstra tajam menghasilkan rasa keju yang lebih kuat meskipun jumlahnya terbatas. Untuk rasa keju yang lebih kuat dan tambahan vitamin B, aduk 1 hingga 2 sendok makan ragi nutrisi pada 5 menit terakhir memasak.","Tambah grits kering menjadi 1/2 cangkir untuk grits yang lebih kental.","Hindari grits instan. Natriumnya berkisar antara 340 hingga 520 mg per porsi.","Alternatif susu tanpa pemanis seperti susu almond, beras, atau kedelai dapat digunakan sebagai pengganti susu sapi."],["1 karbohidrat","1 susu","1 lemak"]))
L.append(R(3023,"Dip Ayam Buffalo","Ayam Buffalo memiliki semua cita rasa sayap Buffalo yang pedas dan panas dalam dip yang halus dan lezat dengan banyak krim keju dan sour cream. Dan karena dip ini ramah ginjal, seluruh keluarga, teman, dan rekan kerja Anda dapat menikmatinya.","16","1/4 cangkir",
["4 ons krim keju rendah lemak","1/2 cangkir paprika merah panggang dalam botol","1 cangkir sour cream rendah lemak","4 sendok teh saus cabai Tabasco®","2 cangkir daging ayam matang, disuwir"],
["Keluarkan krim keju agar lunak.","Tiriskan paprika merah dan ukur 1/2 cangkir. Haluskan dengan blender atau food processor untuk membuat saus paprika merah.","Dalam mangkuk sedang, campurkan krim keju dan sour cream hingga halus. Tambahkan paprika yang sudah dihaluskan dan 2 sendok teh saus Tabasco. Aduk hingga tercampur.","Tambahkan ayam dan aduk perlahan. Tambahkan saus pedas tambahan 1/2 sendok teh demi 1/2 sendok teh; cicipi dan terus tambahkan saus pedas hingga tingkat kepedasan yang Anda inginkan.","Letakkan campuran dalam slow cooker selama 2 hingga 3 jam dengan api kecil, atau panggang dalam oven pada suhu 350° F selama 30 menit.","Sajikan dip hangat dengan wortel, seledri, mentimun, kembang kol untuk dicolek, atau buat gulungan mini dengan membungkus dip di dalam daun selada atau kubis."],
["Carilah paprika merah panggang dalam botol atau kaleng dengan natrium 85 mg atau kurang per ons, atau panggang paprika merah segar untuk dihaluskan. Paprika merah panggang api Trader Joe’s hanya mengandung 60 mg natrium per ons.","Anda juga dapat menggunakan paprika merah panggang beku jika tersedia.","Merek dan jenis saus pedas sangat bervariasi dalam kandungan natriumnya. Tetaplah menggunakan saus cabai Tabasco® original karena natriumnya jauh lebih rendah. Tambah hingga 6 sendok teh jika Anda menyukai rasa yang lebih pedas.","Sajikan dengan sayuran mentah. Pilihan yang lebih rendah kalium antara lain wortel, seledri, mentimun, kembang kol untuk dicolek, atau daun selada atau kubis untuk gulungan.","Jika disajikan di pesta, panggang lalu pindahkan ke slow cooker kecil agar tetap hangat."],["1 daging"]))
L.append(R(3024,"Ayam dan Pangsit Buatan Sendiri (atau Kalkun)","Saat ini, di dunia makanan cepat saji dan praktis, kita bisa lupa bahwa makanan sederhana yang dibuat dengan bahan-bahan dasar biasanya lebih lezat dan memuaskan. Donna, ahli gizi ginjal DaVita dari Texas, membagikan resep rumahannya untuk Ayam dan Pangsit Buatan Sendiri dan mengajak Anda menambahkan hidangan ini ke dalam diet ginjal sehat Anda. Inilah resep yang dapat Anda ikuti untuk hidangan yang sangat lezat dan tetap mendukung keberhasilan diet dialisis Anda.","8","1-1/4 cangkir",
["5 pon ayam panggang, dipotong-potong","6 cangkir air","1/2 cangkir seledri, dipotong dadu","1/2 sendok teh garam","1/4 sendok teh lada","1/2 sendok teh campuran bumbu herbal Mrs. Dash®","3 cangkir kentang, dikupas dan diiris setebal 1/4”","1 bawang bombai ukuran sedang, diiris","1 cangkir tepung terigu serbaguna putih","1 sendok makan mentega, dilunakkan","1 butir telur, dikocok ringan","3 sendok makan peterseli segar cincang"],
["Kupas dan iris kentang. Rendam dalam panci besar berisi air selama 3-4 jam untuk mengurangi sebagian kalium, atau rebus kentang selama 5 menit, buang airnya, lalu tambahkan air segar dan masak hingga empuk. Masukkan potongan ayam atau kalkun ke dalam Dutch oven bersama 6 cangkir air. Tambahkan seledri, garam, lada, dan bumbu herbal. Didihkan. Kecilkan api dan didihkan perlahan, tertutup, selama 60 menit atau hingga empuk. Lepaskan daging dari tulangnya dan sisihkan.","Masukkan kentang yang sudah direndam atau direbus dua kali dan bawang bombai ke dalam kaldu. Didihkan kaldu dan masak hingga kentang empuk, sekitar 15 menit. Angkat sayuran dengan sendok berlubang dan sisihkan.","Dalam mangkuk besar, campurkan tepung dan mentega dengan garpu. Tambahkan telur dan 2 sendok makan air; aduk dengan garpu hingga bahan-bahan lembap.","Giling adonan setebal 1/3”. Dengan pisau tajam, potong adonan menjadi strip.","Masukkan strip mi ke dalam kaldu dan masak selama 15 menit (Jika menggunakan mi pangsit kemasan siap pakai, cukup masukkan ke dalam kaldu pada saat ini.)","Masukkan sayuran dan daging ke dalam kaldu dan didihkan perlahan selama 5 menit.","Taburi dengan peterseli segar dan sajikan."],
["Untuk kemudahan, Anda dapat menggunakan sebungkus mi pangsit siap pakai seperti merek Mary B’s®, yang dapat ditemukan di bagian makanan beku di toko kelontong Anda.","Jika Anda menjalani diet dengan protein yang dimodifikasi, pilih ayam yang lebih kecil, 2.5 pon, untuk mengurangi protein menjadi 21 gram per porsi.","Ganti ayam dengan 3 paha kalkun, tanpa kulit, tanpa tulang, dan dicincang."],["4 daging","1-1/2 karbohidrat","1/2 sayuran, kalium sedang"]))
L.append(R(3027,"Mangkuk Sayuran Tempe Teriyaki","Tempe adalah kedelai fermentasi. Tempe umumnya rendah natrium dan sumber protein yang sangat baik. Anda bisa berkreasi dengan memotongnya dadu, mengirisnya, atau menghancurkannya dan menambahkannya ke hidangan favorit Anda sebagai pengganti daging.","4","1/3 cangkir nasi, 2 ons tempe, 1/4 dari sayuran",
["1 kemasan tempe 8 ons","1 sendok makan minyak zaitun","2/3 cangkir beras merah","1/4 cangkir coconut aminos","1/4 cangkir air + 4 sendok teh, dibagi","1/4 cangkir madu","1 sendok makan cuka beras","2 sendok teh tepung maizena","1 kantong brokoli beku 12.6 ons","1 batang daun bawang, opsional"],
["Iris tempe menjadi 12 strip pendek secara melintang. Panaskan minyak zaitun dalam wajan dan masukkan tempe. Masak dan balik selama 8-10 menit hingga mulai kecokelatan.","Masak nasi sesuai petunjuk kemasan, lihat Tips Bermanfaat.","Dalam panci kecil kocok bersama coconut aminos, 1/4 cangkir air, madu, dan cuka beras, didihkan. Sementara itu campurkan tepung maizena dan 4 sendok teh air. Masukkan ke dalam saus yang mendidih dan kocok hingga mulai mengental.","Tuang saus di atas tempe dalam panci dan panaskan hingga hangat merata selama 5-8 menit.","Kukus/masak brokoli dalam microwave. Tiriskan jika perlu dan sisihkan.","Bagi nasi ke dalam 4 mangkuk, sekitar 1/3 cangkir per mangkuk. Tambahkan brokoli (1/2 cangkir) ke setiap mangkuk dan letakkan 3 iris tempe di atasnya. Siram setiap mangkuk dengan 2 sendok makan crema. Iris daun bawang dan taburkan di atas setiap mangkuk, jika diinginkan."],
["Menggunakan beras merah instan. Gunakan 1-1/3 cangkir air untuk memasak, didihkan lalu didihkan perlahan dalam keadaan tertutup selama 10 menit.","Kantong sayuran kukus seberat 12.6 ons menghasilkan sekitar 2 cangkir sayuran.","Tempe secara alami rendah natrium. Namun, saat membandingkan merek, pastikan memilih merek dengan natrium terendah. Jika tidak dimarinasi, kandungan natriumnya akan sangat rendah.","Dressing crema dapat ditambahkan sebagai pilihan. Aduk 4 sendok makan sour cream dengan 3 sendok makan air. Ini akan menambah 15 mg kalium dan 9 mg fosfor per porsi."],["1-1/2 protein","1 karbohidrat","1 sayuran, rendah kalium","1 lemak","1 tinggi kalori"]))
L.append(R(3028,"Air Infus Raspberry-Limau","Air putih adalah salah satu minuman paling sehat bagi pasien ginjal, tetapi tidak harus hambar dan tanpa rasa! Cobalah Air Infus Raspberry-Limau, salah satu dari banyak resep air infus dari ahli gizi DaVita, Kara.","10","1 cangkir (8 ons)",
["1 buah limau","12 lembar daun mint","1/2 cangkir raspberry segar","10 cangkir air"],
["Iris tipis limau.","Cincang halus daun mint.","Masukkan semua bahan ke dalam teko.","Dinginkan di lemari es semalaman sebelum disajikan."],
["Tambahkan beberapa buah beri ke setiap cangkir air infus.","Untuk variasi, cobalah stroberi sebagai pengganti raspberry.","Jika Anda membatasi cairan, sesuaikan ukuran porsi dengan kebutuhan Anda.","Setelah rasanya meresap, Anda dapat menuangkannya ke dalam cetakan es batu untuk membuat es batu beraroma."],["tidak ada"]))
L.append(R(3029,"Campuran Bumbu Timur Tengah","Buat campuran bumbu Timur Tengah ini untuk daging, unggas, atau nasi Anda guna menambah rasa tanpa tambahan garam.","12","1 sendok makan",
["1 sendok makan ketumbar bubuk","1 sendok makan jintan bubuk","1 sendok makan kunyit","2 sendok teh daun mint yang dihancurkan","1 sendok teh kayu manis bubuk"],
["Masukkan bahan-bahan ke dalam toples dan kocok hingga tercampur.","Simpan hingga siap digunakan."],
["Gunakan untuk membumbui daging, unggas, atau nasi.","Sesuaikan jumlahnya dengan selera Anda."],["tidak ada"]))
L.append(R(3030,"Pasta Primavera","Pasta Primavera adalah resep ramah ginjal yang sempurna untuk dibuat bagi kelompok besar.","6","1-3/4 cangkir",
["12 ons pasta, belum dimasak","12 ons sayuran campur beku","14 ons kaldu ayam rendah natrium","2 sendok makan tepung terigu serbaguna putih","1/4 cangkir krimer half & half","1/4 sendok teh bawang putih bubuk","1/4 cangkir keju Parmesan parut"],
["Masak pasta dan sayuran dalam panci terpisah sesuai petunjuk kemasan, tetapi tanpa garam. Tiriskan.","Tuang kaldu ayam rendah natrium ke dalam panci rebus berukuran sedang dan panaskan dengan api kecil.","Masukkan tepung ke dalam kaldu sambil dikocok kuat-kuat agar tidak menggumpal.","Tambahkan half and half dan bawang putih bubuk lalu aduk.","Didihkan perlahan dengan api kecil selama 5 hingga 10 menit hingga campuran mengental sedikit. Aduk sesekali saat mendidih.","Tambahkan sayuran dan pasta yang sudah dimasak. Masak hingga panas merata.","Taburi dengan keju Parmesan dan sajikan."],
["Campuran sayuran beku bervariasi dalam kandungan kaliumnya. Pilih campuran dengan sayuran yang lebih rendah kalium atau tanyakan kepada ahli gizi Anda untuk merekomendasikan pilihan terbaik bagi diet Anda jika Anda membatasi kalium.","12 ons pasta mentah setara dengan sekitar 6 cangkir pasta matang."],["3 karbohidrat","1 sayuran, rendah kalium"]))
L.append(R(3031,"Pancake Zucchini","Pancake Zucchini adalah cara kreatif dan cepat bagi penderita penyakit ginjal kronis (PGK) untuk makan sayuran. Dengan tekstur seperti hash brown, resep ini terdiri dari irisan zucchini yang lezat, bawang bombai yang gurih, dan telur yang menyatukan semuanya. Nikmati hidangan sayuran ini dengan satu sendok makan saus apel atau saus cranberry. Pasti akan menjadi favorit!","4","1 pancake",
["2 cangkir zucchini","1/4 cangkir bawang bombai","1 sendok makan tepung terigu serbaguna putih","1 sendok teh campuran bumbu herbal original Mrs. Dash®","1/4 cangkir pengganti telur cair rendah kolesterol","1 sendok makan minyak canola","1/8 sendok teh garam"],
["Parut bawang bombai dan zucchini ke dalam mangkuk lalu aduk hingga tercampur. Letakkan campuran zucchini di atas lap dapur yang bersih. Pilin dan peras sebanyak mungkin cairannya. Kembalikan ke mangkuk.","Campurkan tepung, garam, dan bumbu herbal Mrs. Dash® dalam mangkuk kecil. Tambahkan produk telur dan aduk; aduk ke dalam campuran zucchini dan bawang bombai. Bentuk 4 adonan pipih.","Panaskan minyak dengan api besar dalam wajan antilengket besar. Kecilkan api menjadi sedang dan masukkan adonan zucchini ke dalam wajan. Tumis hingga kecokelatan, balik sekali."],
["Sajikan dengan 1 sendok makan saus apel atau saus cranberry."],["1 sayuran, kalium sedang","1 lemak"]))
L.append(R(3032,"Donat Panggang","Membuat donat buatan sendiri adalah pengalaman yang memuaskan. Resep Donat Panggang dari ahli gizi DaVita, Robin, mencakup tambahan protein serta tepung gandum utuh untuk meningkatkan serat.","12","1 donat atau 4 donat mini",
["5 sendok makan mentega tanpa garam","1/4 cangkir minyak canola","1/4 cangkir gula pasir","1/3 cangkir gula merah padat","2 butir telur besar","1-1/2 sendok teh baking powder","1/4 sendok teh soda kue","1/2 sendok teh pala","1/2 sendok teh garam","1-1/2 sendok teh ekstrak vanila","2 cangkir tepung pastry gandum utuh","2/3 cangkir tepung terigu serbaguna putih","1/4 cangkir bubuk protein vanila","1 cangkir yogurt Yunani plain","1/4 cangkir susu + 1 hingga 2 sendok makan","1-1/4 cangkir gula halus yang diayak","1 sendok makan sirup jagung berwarna terang","1/4 cangkir taburan warna-warni"],
["Panaskan oven terlebih dahulu hingga 425° F. Olesi ringan 2 cetakan donat standar (12 donat) dengan lemak","Dengan mixer listrik, dalam mangkuk sedang, kocok 4 sendok makan mentega, minyak, serta gula pasir dan gula merah hingga halus.","Tambahkan telur, aduk hingga tercampur.","Aduk baking powder, soda kue, pala, garam, dan 1 sendok teh vanila.","Aduk tepung dan bubuk protein ke dalam campuran mentega secara bergantian dengan yogurt dan susu. Mulai dan akhiri dengan campuran tepung. Pastikan semuanya tercampur rata. Adonan akan","cukup kental. Saat Anda menarik spatula melalui adonan, akan meninggalkan lekukan.","Sendokkan adonan ke dalam cetakan donat yang sudah diolesi lemak, isi hingga sekitar 1/4 inci dari bagian atas. Atau, Anda dapat menuang adonan ke dalam cetakan donat menggunakan kantong piping.","Panggang donat selama 10 menit. Angkat cetakan dari oven, dan biarkan donat dingin selama 5 hingga 7 menit. Keluarkan donat dari cetakan dan biarkan dingin sepenuhnya.","Selagi donat mendingin, buat glaze. Aduk gula halus yang diayak, sirup jagung, sisa vanila, mentega (yang dilelehkan), dan 1 sendok makan susu dalam mangkuk dangkal. Tambahkan susu atau","gula halus tambahan sesuai kebutuhan untuk menyesuaikan kekentalan.","Tuang taburan warna-warni ke dalam mangkuk dangkal terpisah.","Celupkan bagian atas donat ke dalam glaze hingga terlapisi, lalu celupkan ke dalam taburan. Letakkan di atas rak hingga mengeras."],
["Anda juga dapat memanggang adonan dalam cetakan muffin mini, lalu beri glaze dan taburan untuk membuat “donat mini”.","Jika tepung pastry gandum utuh tidak tersedia, ganti dengan 1 cangkir tepung gandum utuh dan 1 cangkir tepung terigu serbaguna (selain 2/3 cangkir tepung terigu serbaguna).","Resep ini tinggi protein dan serat serta lebih rendah natrium dibandingkan donat toko roti."],["1-1/2 karbohidrat","1/2 susu","2 lemak","1-1/2 tinggi kalori"]))
L.append(R(3035,"Roti Rye Caraway","Memanggang roti beragi adalah sebuah seni. Munculkan seniman dalam diri Anda dengan resep Roti Rye Caraway dari ahli gizi DaVita, Tara. Rendah natrium dan kaya rasa!","16","1 iris",
["2 cangkir tepung rye","1-1/2 cangkir tepung terigu serbaguna","1 sendok teh garam kosher","1 sendok teh ragi kering aktif","1-1/2 cangkir air hangat","2 sendok teh biji caraway"],
["Dalam stand mixer, campurkan tepung, garam, ragi, dan biji caraway.","Buat cekungan di tengah campuran tepung dan tambahkan air hangat.","Aduk hingga adonan menjadi basah dan lengket.","Tutup dengan plastik pembungkus dan diamkan di tempat hangat dan kering selama 3 jam.","Panaskan oven hingga 450° F. Letakkan Dutch oven enamel beserta tutupnya di dalam oven. Biarkan panas selama 30 menit.","Selagi Dutch oven dipanaskan, keruk adonan dari mangkuk dan letakkan di atas talenan atau meja yang ditaburi tepung.","Taburi tangan Anda dengan tepung dan lipat adonan beberapa kali; bentuk adonan menjadi bola. Letakkan bagian lipatan di bawah adonan.","Keluarkan Dutch oven dari oven dengan hati-hati dan masukkan adonan ke dalamnya. Pasang kembali tutup dan masukkan lagi ke oven. Masak selama 30 menit atau hingga suhu internal roti mencapai 200° F.","Angkat dari oven dan pindahkan ke rak pendingin. Potong roti yang sudah dingin menjadi 16 potong."],
["Untuk kerak yang lebih renyah, dapat dimasak 10 menit lagi dengan tutup Dutch oven dilepas.","Resep ini paling cocok dalam Dutch oven. Loyang roti tidak disarankan."],["1 karbohidrat"]))
L.append(R(3036,"Salad Mentimun Segar Pedas Asam","Resep sederhana ramah ginjal ini penuh rasa dari mentimun, dressing Italia, dan bawang merah bombai. Itulah sebabnya Salad Mentimun Segar Pedas Asam akan muncul di meja makan lebih dari sekali.","14","1/2 cangkir",
["5 cangkir mentimun","2 cangkir bawang merah bombai","1/2 cangkir dressing salad Italia Kraft® Light Done Right!®","1/4 cangkir gula"],
["Kupas dan buang biji mentimun; iris bawang bombai.","Campurkan semua bahan dalam mangkuk besar.","Tutup dan dinginkan di lemari es setidaknya 30 menit untuk marinasi.","Sajikan dingin."],
["Kurangi karbohidrat menjadi 4 gram dengan menggunakan pengganti gula sebagai ganti gula.","Sisa makanan dapat disimpan di lemari es hingga satu minggu."],["1 sayuran, rendah kalium"]))
L.append(R(3037,"Pesto Kemangi","Nikmati satu porsi sayuran yang diblender dalam Pesto Kemangi ini. Pesto ini tambahan yang bagus untuk pasta atau sebagai marinasi atau topping pada makanan laut atau ayam. Resep kreatif ini mengganti keju dengan ragi nutrisi.","12","2 sendok makan",
["2 cangkir daun kemangi segar","2/3 cangkir ragi nutrisi","3 siung bawang putih","1/2 buah lemon segar","1 sendok teh lada hitam","1 cangkir kacang pinus","2 sendok makan minyak biji rami","2 sendok makan minyak zaitun"],
["Peras lemon. Masukkan semua bahan kecuali minyak biji rami dan minyak zaitun ke dalam food processor.","Campurkan kedua minyak dan tuang minyak ke dalam food processor melalui bagian atas agar teremulsi merata saat bahan diblender. Aduk bahan dari dasar blender sesuai kebutuhan.","Simpan pesto dalam toples atau wadah tertutup hingga siap digunakan sebagai marinasi, dressing salad, atau saus pasta. Tahan hingga satu minggu di lemari es."],
["Tambahan 2 sendok makan minyak biji rami dapat digunakan sebagai pengganti minyak zaitun.","Minyak biji rami memberikan manfaat kesehatan, termasuk menyediakan asam lemak omega-3 ALA.","Pesto Kemangi sangat serbaguna- gunakan sebagai marinasi pada makanan laut atau ayam, sebagai saus cocolan untuk sayuran segar atau panggang, dressing salad, atau campurkan dengan pasta atau nasi sebagai alternatif saus tomat yang lebih rendah kalium."],["1 sayuran, kalium sedang","2 lemak"]))
L.append(R(3038,"Saus Kari dengan Ayam","Karen, ahli gizi ginjal DaVita dari California, memberi cita rasa pada diet ginjal dengan Saus Kari yang mengenyangkan dan dapat dipadukan dengan makanan laut, ayam, atau daging sapi. Bebas gula dan dibuat dengan kaldu rendah natrium, saus ini sempurna bagi penderita penyakit ginjal. Saus Kari Karen serbaguna, ramah ginjal, dan cara yang bagus untuk menambahkan sedikit pedas pada daging.","6","1-1/2 cangkir",
["1 siung bawang putih","1 sendok teh akar jahe","1/3 cangkir wortel","1/3 cangkir seledri","1/3 cangkir bawang bombai","1 buah apel kecil","8 ons jamur","3 sendok makan tepung terigu serbaguna putih","2 sendok makan bubuk kari","4 sendok makan minyak sayur","32 ons kaldu ayam rendah natrium","1/2 sendok teh lada putih","1-1/2 pon ayam tanpa tulang"],
["Cincang halus bawang putih dan jahe. Cincang halus wortel, seledri, dan bawang bombai. Iris jamur. Cincang apel.","Campurkan tepung, bawang putih, jahe, bubuk kari, dan minyak sayur dalam wajan dalam antilengket (setidaknya 4 liter) dengan api sedang.","Aduk hingga kari menjadi seperti pasta.","Tambahkan kaldu perlahan, dan aduk hingga saus halus.","Tambahkan sayuran, apel, dan lada putih.","Didihkan perlahan, sambil terus diaduk, selama 15 menit, atau hingga tercampur rata.","Didihkan saus dan masukkan ayam.","Didihkan kari perlahan selama 1-1/2 jam dengan api kecil, aduk secara teratur, lalu sajikan."],
["Hemat waktu dengan menggunakan campuran Mirepoix Trader Joe’s®, wadah berisi wortel, seledri, dan bawang bombai yang sudah dicincang dan dicuci.","Ganti ayam dengan daging sapi atau makanan laut untuk variasi. Jika menggunakan daging sapi mentah, cokelatkan terlebih dahulu sebelum dimasukkan ke dalam kari pada langkah 6.","Bagi penderita PGK non-dialisis yang menjalani diet protein lebih rendah, kurangi porsi menjadi 3/4 cangkir.","Sajikan di atas nasi untuk hidangan lengkap."],["4 daging","1/2 sayuran, kalium sedang"]))
save(3,L)
